<?php

declare(strict_types=1);

namespace App\Controllers;

use App\Models\PromotionAssessmentModel;
use App\Models\PromotionOrderModel;
use App\Models\PromotionPackageModel;
use CodeIgniter\HTTP\ResponseInterface;
use RuntimeException;

/**
 * Streams the PDF reports generated by `App\Services\ReportService`.
 * Unit-scoped users only ever see their own unit's backlog; the other
 * two reports are keyed off a specific package/order, so each action
 * re-verifies unit ownership itself (there is no numeric package/order
 * id as the route's last segment for the `unit-access` filter to read,
 * since these are nested under `reports/`).
 */
class ReportsController extends BaseController
{
    public function backlog(): ResponseInterface
    {
        $user = $this->currentUser();

        $unitScopedId = $user !== null && $user->inGroup('unit_s1_clerk')
            ? (int) $user->organizational_unit_id
            : null;

        $pdf = service('reportService')->backlogReport($unitScopedId);

        return $this->response
            ->setContentType('application/pdf')
            ->setBody($pdf);
    }

    /**
     * The backlog as a spreadsheet rather than a PDF.
     *
     * Staff work the backlog list -- they sort it, annotate it, and hand parts
     * of it to different desks -- which a PDF does not allow.
     */
    public function backlogCsv(): ResponseInterface
    {
        $user = $this->currentUser();

        $unitScopedId = $user !== null && $user->inGroup('unit_s1_clerk')
            ? (int) $user->organizational_unit_id
            : null;

        $overdue = (new PromotionAssessmentModel())->overdueReservists($unitScopedId);

        // Columns named explicitly so an empty backlog still exports a usable
        // header row rather than a blank file, and so the export does not
        // silently change shape when the query gains a column.
        $columns = [
            'reservist_number', 'last_name', 'first_name', 'unit_name', 'rank_name',
            'track_name', 'time_in_grade_months', 'as_of_date', 'promotion_status',
            'requires_manual_review',
        ];

        return $this->response->download(
            'promotion-backlog-' . date('Ymd') . '.csv',
            csv_from_rows($overdue, $columns)
        )->setContentType('text/csv');
    }

    public function promotionOrder(?int $promotionOrderId = null): ResponseInterface
    {
        if ($promotionOrderId === null) {
            throw new RuntimeException('A promotion order id is required.');
        }

        $order = (new PromotionOrderModel())
            ->select('promotion_orders.*, promotion_packages.organizational_unit_id')
            ->join('promotion_packages', 'promotion_packages.id = promotion_orders.promotion_package_id')
            ->find($promotionOrderId);

        if ($order === null) {
            throw new RuntimeException("Promotion order #{$promotionOrderId} was not found.");
        }

        if (! $this->belongsToUserUnit((int) $order['organizational_unit_id'])) {
            throw new RuntimeException('You are not authorized to access this promotion order.');
        }

        $pdf = service('reportService')->promotionOrderDraft($promotionOrderId);

        return $this->response
            ->setContentType('application/pdf')
            ->setBody($pdf);
    }

    public function endorsements(?int $packageId = null): ResponseInterface
    {
        if ($packageId === null) {
            throw new RuntimeException('A package id is required.');
        }

        $package = (new PromotionPackageModel())->find($packageId);

        if ($package === null) {
            throw new RuntimeException("Promotion package #{$packageId} was not found.");
        }

        if (! $this->belongsToUserUnit((int) $package['organizational_unit_id'])) {
            throw new RuntimeException('You are not authorized to access this promotion package.');
        }

        $pdf = service('reportService')->endorsementReport($packageId);

        return $this->response
            ->setContentType('application/pdf')
            ->setBody($pdf);
    }
}
